// md-exfil T12: the headers of every route that streams stored or generated bytes.
//
//   node --test server/artifactHeaders.test.ts
import test from 'node:test'
import assert from 'node:assert/strict'
import { ARTIFACT_CSP, isRasterImageType, setArtifactHeaders } from './artifactHeaders.ts'

function fakeRes() {
  const headers: Record<string, string> = {}
  return { headers, setHeader: (k: string, v: string) => void (headers[k.toLowerCase()] = v) }
}

test('the policy is the strict sandboxed one', () => {
  assert.equal(ARTIFACT_CSP, "default-src 'none'; img-src 'self' data:; style-src 'unsafe-inline'; sandbox")
})

test('raster image types are the only ones that may render inline', () => {
  for (const t of ['image/png', 'image/jpeg', 'image/gif', 'image/webp', 'image/avif', 'IMAGE/PNG', 'image/png; charset=binary']) assert.equal(isRasterImageType(t), true, t)
  for (const t of ['image/svg+xml', 'image/svg+xml; charset=utf-8', 'text/html', 'application/xhtml+xml', 'application/pdf', 'image/x-unknown', '', undefined, null]) assert.equal(isRasterImageType(t as string), false, String(t))
})

test('a download carries the policy, nosniff, the type and an attachment name', () => {
  const r = fakeRes()
  setArtifactHeaders(r, { contentType: 'application/vnd.openxmlformats-officedocument.presentationml.presentation', filename: 'Deck_1.pptx' })
  assert.equal(r.headers['content-security-policy'], ARTIFACT_CSP)
  assert.equal(r.headers['x-content-type-options'], 'nosniff')
  assert.equal(r.headers['content-type'], 'application/vnd.openxmlformats-officedocument.presentationml.presentation')
  assert.equal(r.headers['content-disposition'], 'attachment; filename="Deck_1.pptx"')
})

test('an SVG is an attachment even when the caller offers no filename', () => {
  const r = fakeRes()
  setArtifactHeaders(r, { contentType: 'image/svg+xml', fallbackName: 'image-7.svg' })
  assert.equal(r.headers['content-type'], 'image/svg+xml')
  assert.equal(r.headers['content-disposition'], 'attachment; filename="image-7.svg"')
  assert.equal(r.headers['content-security-policy'], ARTIFACT_CSP)
})

test('a PNG stays inline (an <img> never runs script) but keeps the policy and nosniff', () => {
  const r = fakeRes()
  setArtifactHeaders(r, { contentType: 'image/png', fallbackName: 'image-7.png', inlineRaster: true })
  assert.equal(r.headers['content-disposition'], undefined)
  assert.equal(r.headers['x-content-type-options'], 'nosniff')
  assert.equal(r.headers['content-security-policy'], ARTIFACT_CSP)
})

test('inlineRaster never lets a non-raster type render inline', () => {
  for (const t of ['image/svg+xml', 'text/html']) {
    const r = fakeRes()
    setArtifactHeaders(r, { contentType: t, fallbackName: 'x.bin', inlineRaster: true })
    assert.match(r.headers['content-disposition'], /^attachment/, t)
  }
})

test('a filename cannot break out of the header', () => {
  const r = fakeRes()
  setArtifactHeaders(r, { contentType: 'text/markdown; charset=utf-8', filename: 'a"\r\nSet-Cookie: x=1.md' })
  assert.doesNotMatch(r.headers['content-disposition'], /[\r\n]/)
  assert.equal(r.headers['content-disposition'].split('"').length, 3)
})
